  select to_jsonb(p)-'allow_student_price_stacking'-'instructor_reward_eligible' into observed from public.promotions p where id=(expected->>'id')::uuid;
  select md5(coalesce(jsonb_agg(to_jsonb(s) order by s.id)::text,'[]')) into digest from public.promotion_scopes s where promotion_id=(expected->>'id')::uuid;
  if observed is distinct from expected-'scope_digest' or digest is distinct from expected->>'scope_digest'
   or exists(select 1 from public.coupon_promotions where promotion_id=(expected->>'id')::uuid) then raise exception 'Target changed: %',expected->>'id';end if;
 end loop;
 update public.promotions set allow_student_price_stacking=false,instructor_reward_eligible=false,updated_at=clock_timestamp() where id=any(ids) and allow_student_price_stacking and instructor_reward_eligible;
