  select to_jsonb(p)-'allow_student_price_stacking'-'instructor_reward_eligible'-'updated_at' into observed from public.promotions p where id=(expected->>'id')::uuid;
  if observed is distinct from expected-'scope_digest'-'updated_at' then raise exception 'Unintended activity change';end if;
 end loop;
 select jsonb_agg(to_jsonb(p) order by id) into after_other from public.promotions p where not(id=any(ids));
 if before_other is distinct from after_other then raise exception 'Other activities changed';end if;
 update public.promotion_student_policy_settings set enabled=true,version=version+1 where singleton;
 if not public.promotion_student_policy_enabled() then raise exception 'New policy not active';end if;
end $activate$;
commit;
select jsonb_build_object('new_policy',(select to_jsonb(s) from public.promotion_student_policy_settings s where singleton),'allocation_enabled',(select enabled from public.automatic_price_allocation_settings where singleton),'restricted_activity_count',(select count(*) from public.promotions where not allow_student_price_stacking and not instructor_reward_eligible),'double_eleven',(select jsonb_agg(jsonb_build_object('id',id,'name',name,'roles',audience_roles,'start_at',start_at,'end_at',end_at,'allow_student_price_stacking',allow_student_price_stacking,'instructor_reward_eligible',instructor_reward_eligible) order by id) from public.promotions where name ilike '%11.11%' and archived_at is null)) as activated;
